shopify.query:
query AdsHeartbeatSep12AfternoonOrderCounts {
shop { id name ianaTimezone }
allNew: ordersCount(query:"created_at:>='2026-09-12T10:49:23Z' created_at:<'2026-09-12T14:49:48Z'",limit:null){count precision}
webNonTest: ordersCount(query:"created_at:>='2026-09-12T10:49:23Z' created_at:<'2026-09-12T14:49:48Z' source_name:web test:false",limit:null){count precision}
paidWebNonTest: ordersCount(query:"created_at:>='2026-09-12T10:49:23Z' created_at:<'2026-09-12T14:49:48Z' source_name:web test:false financial_status:paid",limit:null){count precision}
}
